// generated by pipeline/build.js — data desk map markings loader
// markSVG(name) -> cached svg text; fills are currentColor, so inline it in html and tint via css color
const _svg = {}
export function markSVG(name, base = new URL('markings/', import.meta.url)) {
  return _svg[name] ??= fetch(new URL(name + '.svg', base)).then(r => r.text())
}
// addMarking(map, 'triangle', {color:'#FD7700'}) then use icon-image 'triangle-#FD7700' in a symbol layer
export async function addMarking(map, name, { color = '#FFFFFF', base, scale = 2 } = {}) {
  const svg = (await markSVG(name, base)).replaceAll('currentColor', color)
  const img = new Image()
  const [, w, h] = svg.match(/width="(\d+)" height="(\d+)"/).map(Number)
  img.width = w * scale; img.height = h * scale
  await new Promise((ok, err) => { img.onload = ok; img.onerror = err; img.src = 'data:image/svg+xml;base64,' + btoa(svg) })
  const id = name + '-' + color
  if (!map.hasImage(id)) map.addImage(id, img, { pixelRatio: scale })
  return id
}
export const markings = {
 "triangle": "structure (e.g. oil and gas facilities), variant 1",
 "diamond": "structure, variant 2",
 "square": "structure, variant 3",
 "flare": "flare",
 "quantitative": "quantitative data point; colour may encode intensity (white→orange→red ramp shown pdf:76, mapping unspecified)",
 "vessel": "vessel",
 "waypoint": "waypoint",
 "highlight": "highlight box; heavy-stroke empty square framing a resolved point of interest (see areas.highlight)"
}
